import { useCallback, useEffect, useMemo, useState, type InputHTMLAttributes, type ReactNode } from 'react';
import { useNavigate } from 'react-router-dom';
import { Activity, ArrowLeft, Bell, ChevronDown, Cloud, Database, Download, FileCheck2, FileText, FolderOpen, Layers, LockKeyhole, Mail, MoreHorizontal, Pencil, Plus, RefreshCw, Search, Settings2, Shield, ShieldCheck, Trash2, Users, UserRound, Wallet, type LucideIcon } from 'lucide-react';
import { useAuth } from '../auth/AuthContext';
import { adminApi, type AdminAudit, type AdminGroup, type AdminLayer, type AdminNotice, type AdminPlan, type AdminUser, type Raw } from './adminApi';
import { AdminDataTable } from './AdminDataTable';
import { Dialog as AccessibleDialog } from '../../components/Dialog';
import { Alert } from '../../components/Alert';
import './admin.css';

type Tab = 'users'|'teams'|'plans'|'models'|'layers'|'notices'|'documents'|'security';
type PanelData = {users:AdminUser[];plans:AdminPlan[];layers:AdminLayer[];groups:AdminGroup[];notices:AdminNotice[];audits:AdminAudit[];sessions:Raw[];attempts:Raw[];dashboard:Raw|null;settings:Raw|null};
const empty:PanelData={users:[],plans:[],layers:[],groups:[],notices:[],audits:[],sessions:[],attempts:[],dashboard:null,settings:null};
const tabs:{id:Tab;label:string;description:string;icon:LucideIcon}[]=[
 {id:'users',label:'Usuários',description:'Contas e acesso',icon:Users},
 {id:'teams',label:'Equipes',description:'Licenças compartilhadas',icon:UserRound},
 {id:'plans',label:'Planos e permissões',description:'Assinaturas',icon:Wallet},
 {id:'models',label:'Modelos',description:'Memoriais',icon:FileText},
 {id:'layers',label:'Camadas do sistema',description:'Catálogo geográfico',icon:Layers},
 {id:'notices',label:'Avisos e manutenção',description:'Comunicados',icon:Bell},
 {id:'documents',label:'Documentos dos planos',description:'Termos e comprovantes',icon:FileCheck2},
 {id:'security',label:'Segurança e sessões',description:'Auditoria e sessões',icon:ShieldCheck}
];
const formats=[{id:'standard',name:'Padrão do Surveyor',img:''},{id:'dourado',name:'Dourado',img:'01_Dourado.webp'},{id:'ciano',name:'Ciano',img:'02_Ciano.webp'},{id:'verde',name:'Verde',img:'03_Verde.webp'},{id:'amarelo',name:'Amarelo',img:'04_Amarelo.webp'},{id:'agro-mais',name:'Agro+',img:'05_AgroMais.webp',restricted:true}];
const permissions:[string,string[]][]=[
 ['Mapa',['map:access','map:draw-basic','map:measure-basic','map:coordinates','map:export-kml','map:export-geojson']],
 ['Projetos',['projects:create','projects:edit-own','projects:view-own','projects:export-full','projects:version-full','projects:trash','projects:export-zip']],
 ['Camadas e SIG',['layers:official','layers:view-full','layers:catalog-full','layers:wms-wfs','geometry:vertices-edit','sig:advanced']],
 ['Documentos',['documents:memorial','documents:ods','documents:confrontacao','documents:mapas','documents:pranchas','documents:download']],
 ['Equipe e nuvem',['workspace:members','workspace:storage','cloud:access','cloud:pro','sharing:full']]
];
const human=(raw:unknown,fallback='Não informado')=>typeof raw==='string'||typeof raw==='number'?String(raw):fallback;
const shortDate=(raw:unknown)=>{if(!raw)return 'Não informado';const d=new Date(String(raw));return Number.isFinite(d.getTime())?d.toLocaleDateString('pt-BR'):String(raw);};
const prettyDate=(raw:unknown)=>{if(!raw)return 'Sem registro';const d=new Date(String(raw));return Number.isFinite(d.getTime())?d.toLocaleString('pt-BR'):String(raw);};
const statusText=(value:unknown)=>{const s=String(value||'active').toLowerCase();return s==='active'?'Ativo':s==='blocked'?'Bloqueado':s==='expired'?'Vencido':s==='pending'?'Pendente':String(value||'Não informado');};
const normalizeNoticeAudience=(value:unknown):'all'|'users'|'admins'|'plan'|'user'=>{
 const audience=String(value??'all').trim().toLowerCase();
 if(['users','active','active-users','active_users'].includes(audience))return 'users';
 if(['admins','admin','administrators','administradores'].includes(audience))return 'admins';
 if(['plan','specific-plan','specific_plan','plano'].includes(audience))return 'plan';
 if(['user','specific-user','specific_user','usuario','usuário'].includes(audience))return 'user';
 return 'all';
};
const normalizeNoticeType=(value:unknown):'info'|'success'|'warning'|'danger'|'maintenance'=>{
 const type=String(value??'info').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\s_-]+/g,'');
 if(['success','sucesso'].includes(type))return 'success';
 if(['warning','alert','aviso','alerta'].includes(type))return 'warning';
 if(['danger','urgent','urgente','error','erro','critical','critico'].includes(type))return 'danger';
 if(['maintenance','manutencao'].includes(type))return 'maintenance';
 return 'info';
};
const noticeIsActive=(notice:AdminNotice)=>{
 if(typeof notice.isActive==='boolean')return notice.isActive;
 if(notice.isActive!==undefined&&notice.isActive!==null){const active=String(notice.isActive).trim().toLowerCase();if(['true','1','active'].includes(active))return true;if(['false','0','inactive','disabled','blocked','expired'].includes(active))return false;}
 return !['inactive','disabled','blocked','expired','false','0'].includes(String(notice.status??'active').trim().toLowerCase());
};
const noticeAudienceText=(value:unknown)=>({all:'Todos',users:'Usuários',admins:'Administradores',plan:'Plano específico',user:'Usuário específico'} as Record<string,string>)[normalizeNoticeAudience(value)];
const noticeTypeText=(value:unknown)=>({info:'Informação',success:'Sucesso',warning:'Alerta',danger:'Urgente',maintenance:'Manutenção'} as Record<string,string>)[normalizeNoticeType(value)];
const toLocalDateTime=(value:unknown)=>{if(typeof value!=='string'&&typeof value!=='number')return '';const date=new Date(value);return Number.isFinite(date.getTime())?new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16):'';};
const fromLocalDateTime=(value:unknown)=>{const raw=String(value||'').trim();if(!raw)return null;const date=new Date(raw);return Number.isFinite(date.getTime())?date.toISOString():null;};
const number=(v:unknown)=>{const n=Number(v);return Number.isFinite(n)?n:0;};
const obj=(v:unknown):Raw=>v && typeof v==='object'&&!Array.isArray(v)?v as Raw:{};
const teamMembers=(v:Raw|null):Raw[]=>{const raw=Array.isArray(v?.members)?v?.members:obj(v?.team).members;return Array.isArray(raw)?raw.map(obj):[];};
const field=(value:string|number|undefined,onChange:(s:string)=>void,label:string,props:InputHTMLAttributes<HTMLInputElement>={})=><label className="admin-field"><span>{label}</span><input {...props} value={value??''} onChange={e=>onChange(e.target.value)}/></label>;
function Action({icon:Icon,children,onClick,primary=false,critical=false,disabled=false}:{icon?:LucideIcon;children:ReactNode;onClick:()=>void;primary?:boolean;critical?:boolean;disabled?:boolean}){return <button type="button" disabled={disabled} className={`admin-action${primary?' strong':''}${critical?' critical':''}`} onClick={onClick}>{Icon&&<Icon size={15}/>} {children}</button>}
function Chip({children,good=true}:{children:ReactNode;good?:boolean}){return <span className={`admin-chip ${good?'positive':'negative'}`}>{children}</span>}
function Dialog({title,subtitle,children,onClose,wide=false,closeOnBackdrop=true}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void;wide?:boolean;closeOnBackdrop?:boolean}){
 return <AccessibleDialog title={title} description={subtitle} onClose={onClose} closeOnEscape closeOnBackdrop={closeOnBackdrop} className={wide?'admin-dialog wide':'admin-dialog'}>{children}</AccessibleDialog>;
}
export function AdminPage(){
 const {session}=useAuth();const navigate=useNavigate();
 const administrator=String(session?.user?.role||'').trim().toLowerCase()==='admin';
 const [tab,setTab]=useState<Tab>('users');const [data,setData]=useState<PanelData>(empty);const [loading,setLoading]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [success,setSuccess]=useState('');const [search,setSearch]=useState('');const [modal,setModal]=useState<'user'|'email'|'team'|'plan'|'layer'|'group'|'notice'|'detail'|'model-access'|null>(null);
 const [selected,setSelected]=useState<AdminUser|AdminPlan|AdminLayer|AdminNotice|null>(null);
 const [form,setForm]=useState<Raw>({});const [expandedPlan,setExpandedPlan]=useState<string|null>(null);const [teamInfo,setTeamInfo]=useState<Raw|null>(null);const [memberOpen,setMemberOpen]=useState(false);const [memberForm,setMemberForm]=useState({name:'',email:'',password:'',role:'user'});
 const [activeModel,setActiveModel]=useState<{id:string;name:string;restricted:boolean}|null>(null);
 const [confirmation,setConfirmation]=useState<{title:string;description:string;label:string;action:()=>void}|null>(null);
 const askConfirmation=(title:string,description:string,label:string,action:()=>void)=>setConfirmation({title,description,label,action});
 const [modelAccess,setModelAccess]=useState<string[]>([]);
 const [modelSearch,setModelSearch]=useState('');
 const [documents,setDocuments]=useState({kind:'adesao',planId:'',name:'',email:'',cpf:'',payment:'Pix',amount:'',date:new Date().toISOString().slice(0,10),signature:''});
 const api=useMemo(()=>session?adminApi(session):null,[session]);
 const refresh=useCallback(async(current:Tab)=>{
  if(!api||!administrator)return;
  setLoading(true);setError('');setSuccess('');
  try{
   if(current==='users'||current==='teams'||current==='models'){
    const [users,plans]=await Promise.all([api.users(),api.plans()]);setData(prev=>({...prev,users,plans}));
   }else if(current==='plans'){
    const plans=await api.plans();setData(prev=>({...prev,plans}));
   }
   else if(current==='layers'){
    const [layers,groups]=await Promise.all([api.layers(),api.groups()]);setData(prev=>({...prev,layers,groups}));
    }else if(current==='notices'){
     const [notices,users,plans]=await Promise.all([api.notices(),api.users(),api.plans()]);setData(prev=>({...prev,notices,users,plans}));
   }
   else if(current==='security'){
    const result=await Promise.allSettled([api.dashboard(),api.sessions(),api.audits(),api.loginAttempts(),api.settings()]);
    setData(prev=>({...prev,
     dashboard:result[0].status==='fulfilled'?result[0].value:prev.dashboard,
     sessions:result[1].status==='fulfilled'?result[1].value:prev.sessions,
     audits:result[2].status==='fulfilled'?result[2].value:prev.audits,
     attempts:result[3].status==='fulfilled'?result[3].value:prev.attempts,
     settings:result[4].status==='fulfilled'?result[4].value:prev.settings,
    }));
    const failures=result.filter(v=>v.status==='rejected');if(failures.length)throw new Error(`${failures.length} serviço(s) de segurança indisponível(is). Os dados disponíveis continuam visíveis.`);
   }else if(current==='documents'){
    const plans=await api.plans();setData(prev=>({...prev,plans}));
   }
  }catch(e){setError(e instanceof Error?e.message:'Falha ao carregar os dados.');}finally{setLoading(false)}
 },[api,administrator]);
 useEffect(()=>{void refresh(tab)},[refresh,tab]);
 const changeTab=(next:Tab)=>{setTab(next);setSearch('');setModal(null)};
 const run=async(operation:()=>Promise<unknown>,message:string,after:Tab=tab)=>{setBusy(true);setError('');setSuccess('');try{await operation();setSuccess(message);setModal(null);await refresh(after);setSuccess(message);}catch(e){setError(e instanceof Error?e.message:'Não foi possível executar a operação.')}finally{setBusy(false)}};
 const update=(key:string,value:unknown)=>setForm(prev=>({...prev,[key]:value}));
 const openUser=(user?:AdminUser)=>{setSelected(user||null);setForm(user?{name:user.name,email:user.email,phone:user.phone||user.whatsapp||'',role:user.role,status:user.status,planSlug:user.planSlug||'',expiresAt:user.expiresAt?String(user.expiresAt).slice(0,10):'',password:''}:{name:'',email:'',phone:'',role:'user',status:'active',planSlug:data.plans[0]?.slug||'',expiresAt:new Date(Date.now()+365*86400000).toISOString().slice(0,10),password:''});setModal('user')};
 const openPlan=(plan?:AdminPlan)=>{setSelected(plan||null);setForm(plan?{...plan,priceCents:number(plan.priceCents),permissions:Array.isArray(plan.permissions)?plan.permissions:[]}:{name:'',slug:'',billingCycle:'annual',priceCents:0,maxMembers:1,maxStorageMb:200,isActive:true,permissions:[]});setModal('plan')};
 const openLayer=(layer?:AdminLayer)=>{setSelected(layer||null);setForm(layer?{...layer,color:String(obj(layer.style).color||'#eab308')}:{name:'',groupId:data.groups[0]?.id||'',sourceName:'',serviceUrl:'',geometryType:'polygon',published:false,color:'#eab308'});setModal('layer')};
 const openNotice=(notice?:AdminNotice)=>{setSelected(notice||null);setForm(notice?{...notice,status:noticeIsActive(notice)?'active':'inactive',startsAt:toLocalDateTime(notice.startsAt),endsAt:toLocalDateTime(notice.endsAt),audience:normalizeNoticeAudience(notice.audience),type:normalizeNoticeType(notice.type||notice.category)}:{title:'',message:'',type:'info',displayMode:'notification',status:'active',audience:'all',targetPlanSlug:'',targetUserId:'',startsAt:'',endsAt:'',requiresAck:false,blocksApp:false});setModal('notice')};
 const openModelAccess=(model:typeof formats[number])=>{setActiveModel({id:model.id,name:model.name,restricted:Boolean(model.restricted)});setModelSearch('');setModelAccess(data.users.filter(u=>!u.isSubuser).filter(u=>!model.restricted || (Array.isArray(u.allowedMemorialTemplateIds)&&u.allowedMemorialTemplateIds.includes(model.id))).map(u=>u.id));setModal('model-access');};
 const saveModelAccess=async()=>{
  if(!api||!activeModel)return;
  if(!activeModel.restricted){setError('Os modelos globais são liberados para todos pelo servidor. Para restringi-los individualmente, a API precisa oferecer essa permissão.');setModal(null);return;}
  setBusy(true);setError('');setSuccess('');
  try{
   const owners=data.users.filter(u=>!u.isSubuser&&u.id);
   const changed=owners.filter(u=>{const list=Array.isArray(u.allowedMemorialTemplateIds)?u.allowedMemorialTemplateIds as string[]:[];return list.includes(activeModel.id)!==modelAccess.includes(u.id)});
   for(const u of changed){
    const current=Array.isArray(u.allowedMemorialTemplateIds)?u.allowedMemorialTemplateIds as string[]:[];
    const next=modelAccess.includes(u.id)?[...new Set([...current,activeModel.id])]:current.filter(id=>id!==activeModel.id);
    await api.saveUser({allowedMemorialTemplateIds:next},u.id);
   }
   const verified=await api.users();
   const failed=changed.filter(u=>{const now=verified.find(x=>x.id===u.id);return !now||!Array.isArray(now.allowedMemorialTemplateIds)||now.allowedMemorialTemplateIds.includes(activeModel.id)!==modelAccess.includes(u.id)});
   setData(prev=>({...prev,users:verified}));
   if(failed.length)throw new Error('O servidor não confirmou as permissões de: '+failed.map(u=>u.name).join(', ')+'. Verifique a API.');
   setSuccess('Permissões do modelo confirmadas pela API.');setModal(null);
  }catch(e){setError(e instanceof Error?e.message:'Falha ao salvar permissões.');}finally{setBusy(false)}
 };
 const saveUserConfirmed=async(body:Raw,userId?:string)=>{
  if(!api)throw new Error('Sessão indisponível.');
  await api.saveUser(body,userId);
  const list=await api.users();
  const expected=String(body.name||'').trim();
  const found=userId?list.find(x=>x.id===userId):list.find(x=>x.email?.toLowerCase()===String(body.email).toLowerCase());
  if(!found||(body.name!==undefined&&found.name?.trim()!==expected))throw new Error('A API recebeu a operação, mas não confirmou os dados gravados. Atualize e confira o usuário.');
  if(body.status && String(found.status)!==String(body.status))throw new Error('A API não confirmou a alteração de status do usuário.');
  if(body.expiresAt!==undefined && String(found.expiresAt||'').slice(0,10)!==String(body.expiresAt||'').slice(0,10))throw new Error('A API não confirmou a nova data de validade do plano.');
  if(body.planSlug!==undefined && String(found.planSlug||'')!==String(body.planSlug||''))throw new Error('A API não confirmou a alteração do plano.');
  setData(prev=>({...prev,users:list}));
 };
 const openTeam=async(user:AdminUser)=>{if(!api)return;setSelected(user);setTeamInfo(null);setMemberOpen(false);setForm({teamName:user.workspaceName||''});setModal('team');try{setTeamInfo(await api.team(user.id))}catch(e){setError(e instanceof Error?e.message:'Não foi possível ler a equipe.')}};
 const manageMember=async(ownerId:string,operation:()=>Promise<unknown>,message:string)=>{if(!api)return;setBusy(true);setError('');try{await operation();setSuccess(message);setTeamInfo(await api.team(ownerId));setMemberOpen(false);setMemberForm({name:'',email:'',password:'',role:'user'});}catch(e){setError(e instanceof Error?e.message:'Falha ao gerenciar o membro.')}finally{setBusy(false)}};
 const filteredUsers=data.users.filter(u=>`${u.name} ${u.email} ${u.role} ${u.planName||''} ${u.status}`.toLowerCase().includes(search.toLowerCase()));
 const filteredPlans=data.plans.filter(p=>`${p.name} ${p.slug}`.toLowerCase().includes(search.toLowerCase()));
 const filteredLayers=data.layers.filter(l=>`${l.name} ${l.sourceName||''} ${l.groupName||''}`.toLowerCase().includes(search.toLowerCase()));
 if(!administrator)return <main className="admin-denied"><Shield size={32}/><h1>Acesso restrito</h1><p>Esta área é destinada a administradores autorizados pelo servidor.</p><Action onClick={()=>navigate('/')} icon={ArrowLeft}>Voltar ao Surveyor</Action></main>;
 const editId=selected?.id;
 const displayPlan=(u:AdminUser)=>u.planName||data.plans.find(p=>p.slug===u.planSlug||p.id===u.planId)?.name||u.planSlug||'Não vinculado';
 const formText=(k:string)=>String(form[k]??'');
 return <div className="admin-page">
  <header className="admin-topbar"><div className="admin-brand"><img src="/brand/nome.png" alt="Surveyor"/></div><div className="admin-top-actions"><span className="admin-identity"><ShieldCheck size={16}/> Painel administrativo</span><Action icon={ArrowLeft} onClick={()=>navigate('/')}>Voltar ao Surveyor</Action><span className="admin-top-user"><span className="admin-avatar">{(session?.user?.name||'A')[0]}</span>{session?.user?.name||session?.user?.email}</span></div></header>
  <div className="admin-body"><aside className="admin-sidebar"><p className="admin-sidebar-kicker">GERENCIAMENTO</p><nav aria-label="Áreas da administração">{tabs.map(item=><button key={item.id} className={tab===item.id?'active':''} onClick={()=>changeTab(item.id)}><item.icon size={18}/><span>{item.label}</span>{tab===item.id&&<span className="admin-sidebar-indicator"/>}</button>)}</nav><div className="admin-sidebar-bottom"><LockKeyhole size={16}/><span>Operações protegidas pela autenticação do servidor.</span></div></aside>
   <main className="admin-content"><div className="admin-title-row"><div><span className="admin-overline">CENTRAL DE CONTROLE</span><h1>Administração do sistema</h1><p>Gerencie usuários, assinaturas, serviços e atividades do Surveyor.</p></div><Action icon={RefreshCw} disabled={loading} onClick={()=>void refresh(tab)}>Atualizar dados</Action></div>
    <div className="admin-current-section"><div className="admin-section-heading"><span className="admin-section-icon">{(()=>{const C=tabs.find(t=>t.id===tab)?.icon||Settings2;return <C size={22}/>})()}</span><div><h2>{tabs.find(t=>t.id===tab)?.label}</h2><p>{tabs.find(t=>t.id===tab)?.description}</p></div></div>{loading&&<span className="admin-loading">Consultando a API...</span>}</div>
     {error&&<Alert variant="error" onDismiss={()=>setError('')}><strong>Não foi possível concluir</strong><p>{error}</p></Alert>}
     {success&&<Alert variant="success" onDismiss={()=>setSuccess('')}><strong>Concluído</strong><p>{success}</p></Alert>}
    {tab==='users'&&<><div className="admin-stats"><Stat label="Usuários cadastrados" value={data.users.length} icon={Users}/><Stat label="Contas ativas" value={data.users.filter(u=>String(u.status).toLowerCase()==='active').length} icon={ShieldCheck}/><Stat label="Planos disponíveis" value={data.plans.filter(p=>p.isActive!==false).length} icon={Wallet}/></div><div className="admin-panel"><div className="admin-panel-head"><div><h3>Usuários do sistema</h3><p>Contas, perfis, vigência e ações administrativas.</p></div><div className="admin-toolbar"><Action primary icon={Plus} onClick={()=>openUser()}>Criar usuário</Action></div></div><AdminDataTable rows={filteredUsers} getId={user=>user.id} label="usuários" emptyText="Não há usuários para os filtros selecionados." loading={loading} copyValue={user=>user.email} columns={[{id:'user',label:'USUÁRIO',value:user=>`${user.name} ${user.email}`,render:user=><div className="admin-person"><span className="admin-avatar soft">{user.name?.[0]||'U'}</span><div><b>{user.name||'Sem nome'}</b><small>{user.email}</small></div></div>},{id:'profile',label:'PERFIL / PLANO',value:user=>`${user.role} ${displayPlan(user)}`,render:user=><><strong>{user.role==='admin'?'Administrador':user.isSubuser?'Colaborador':user.role==='technician'?'Técnico':user.role||'Usuário'}</strong><small>{displayPlan(user)}</small></>},{id:'expires',label:'VENCIMENTO',value:user=>user.expiresAt||'',render:user=>shortDate(user.expiresAt)},{id:'status',label:'STATUS',value:user=>statusText(user.status),render:user=><Chip good={user.status==='active'}>{statusText(user.status)}</Chip>}]} rowActions={user=><><Action icon={Pencil} onClick={()=>openUser(user)}>Editar</Action><Action icon={MoreHorizontal} onClick={()=>{setSelected(user);setModal('detail')}}>Detalhes</Action></>}/></div></>}
    {tab==='teams'&&<div className="admin-panel"><div className="admin-panel-head"><div><h3>Equipes e licenças</h3><p>Controle titulares, vagas de membros e armazenamento compartilhado.</p></div><SearchField value={search} change={setSearch} placeholder="Localizar equipe"/></div><div className="admin-card-grid">{filteredUsers.filter(u=>!u.isSubuser).map(u=><article className="admin-entity-card" key={u.id}><div className="admin-card-title"><span className="admin-avatar soft">{u.name?.[0]}</span><div><h3>{human(u.workspaceName,u.name)}</h3><small>{u.email}</small></div><Chip good={u.status==='active'}>{statusText(u.status)}</Chip></div><div className="admin-card-meta"><span><b>Plano</b>{displayPlan(u)}</span><span><b>Membros</b>{human(obj(u.teamSummary).totalSeats,'Ver equipe')}</span></div><Action icon={Users} onClick={()=>void openTeam(u)}>Gerenciar equipe</Action></article>)}</div></div>}
    {tab==='plans'&&<div className="admin-panel"><div className="admin-panel-head"><div><h3>Planos e permissões</h3><p>Planos oficiais, preços, limites e recursos permitidos.</p></div><div className="admin-toolbar"><SearchField value={search} change={setSearch} placeholder="Buscar plano"/><Action icon={Settings2} disabled={busy} onClick={()=>{askConfirmation('Corrigir planos duplicados','A correção será processada pela API administrativa.','Corrigir',()=>void run(()=>api!.dedupePlans(),'Planos duplicados verificados.'))}}>Corrigir duplicados</Action><Action icon={Plus} primary onClick={()=>openPlan()}>Novo plano</Action></div></div><div className="admin-card-grid">{filteredPlans.map(p=><article className="admin-entity-card" key={p.id}><div className="admin-card-title"><span className="admin-card-icon"><Wallet size={20}/></span><div><small>{p.billingCycle||'Assinatura'}</small><h3>{p.name}</h3></div><Chip good={p.isActive!==false}>{p.isActive!==false?'Ativo':'Inativo'}</Chip></div><strong className="admin-price">{(number(p.priceCents)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}</strong><div className="admin-card-meta"><span><b>Permissões</b>{Array.isArray(p.permissions)?p.permissions.length:0}</span><span><b>Membros</b>{human(p.maxMembers,'Conforme plano')}</span><span><b>Armazenamento</b>{p.maxStorageMb?`${p.maxStorageMb} MB`:'Conforme plano'}</span></div><div className="admin-card-actions"><Action onClick={()=>setExpandedPlan(expandedPlan===p.id?null:p.id)} icon={ChevronDown}>{expandedPlan===p.id?'Recolher':'Ver permissões'}</Action><Action icon={Pencil} onClick={()=>openPlan(p)}>Editar</Action><Action onClick={()=>void run(()=>api!.savePlan({...p,isActive:p.isActive===false},p.id),`Plano ${p.isActive===false?'ativado':'desativado'}.`)}>{p.isActive===false?'Ativar':'Desativar'}</Action></div>{expandedPlan===p.id&&<div className="admin-permissions-view">{Array.isArray(p.permissions)?p.permissions.map(t=><span key={t}>{t}</span>):<p>Não foram retornadas permissões para este plano.</p>}</div>}</article>)}</div></div>}
    {tab==='models'&&<div className="admin-panel"><div className="admin-panel-head"><div><h3>Modelos de memorial</h3><p>Biblioteca de modelos e permissões de utilização.</p></div></div><div className="admin-card-grid models">{formats.map(f=><article key={f.id} className="admin-entity-card admin-model"><div className="admin-model-picture">{f.img?<img src={`/admin-models/${f.img}`} alt={`Modelo ${f.name}`} loading="lazy" decoding="async"/>:<div className="admin-model-placeholder">MEMORIAL<br/>DESCRITIVO</div>}</div><div className="admin-model-main"><span className="admin-tag">{f.restricted?'RESTRITO':'GLOBAL'}</span><h3>{f.name}</h3><small>{f.restricted?'Atribuído individualmente':'Disponível a todos os usuários autorizados'}</small></div><button type="button" className="admin-model-more" aria-label={`Ver permissões do modelo ${f.name}`} title="Gerenciar acessos" onClick={()=>openModelAccess(f)}><MoreHorizontal size={19}/></button></article>)}</div></div>}
    {tab==='layers'&&<div className="admin-panel"><div className="admin-panel-head"><div><h3>Camadas do sistema</h3><p>Serviços oficiais, categorias, publicação e edição.</p></div><div className="admin-toolbar"><SearchField value={search} change={setSearch} placeholder="Nome, grupo ou fonte"/><Action icon={Cloud} onClick={()=>{askConfirmation('Sincronizar catálogo GeoBahia','A sincronização será solicitada à API do catálogo.','Sincronizar',()=>void run(()=>api!.seedGeoBahia(),'Sincronização solicitada.'))}}>Sincronizar GeoBahia</Action><Action icon={Plus} onClick={()=>{setForm({name:''});setModal('group')}}>Novo grupo</Action><Action primary icon={Plus} onClick={()=>openLayer()}>Nova camada</Action></div></div><p className="admin-list-count">{filteredLayers.length} de {data.layers.length} camadas · {data.groups.length} grupos</p><div className="admin-layer-list">{filteredLayers.slice(0,200).map(l=><div className="admin-layer-row" key={l.id}><span className="admin-layer-color" style={{background:String(obj(l.style).color||obj(l.style).fillColor||'#eab308')}}/><div className="admin-layer-info"><b>{l.name}</b><small>{l.groupName||data.groups.find(g=>g.id===l.groupId)?.name||'Sem grupo'} · {l.sourceName||'Fonte não informada'}</small></div><Chip good={l.published!==false}>{l.published===false?'Não publicada':'Publicada'}</Chip><Action onClick={()=>openLayer(l)} icon={Pencil}>Editar</Action><Action onClick={()=>void run(()=>api!.publishLayer(l.id,l.published===false),`Publicação de ${l.name} atualizada.`)}>{l.published===false?'Publicar':'Ocultar'}</Action></div>)}{filteredLayers.length>200&&<p>Mostrando 200 de {filteredLayers.length} resultados. Refine a busca para localizar uma camada.</p>}{!filteredLayers.length&&!loading&&<Empty>Não foram encontradas camadas.</Empty>}</div></div>}
    {tab==='notices'&&<div className="admin-panel"><div className="admin-panel-head"><div><h3>Avisos e manutenção</h3><p>Notificações segmentadas, com tipo, período e status de publicação.</p></div><Action primary icon={Plus} onClick={()=>openNotice()}>Criar aviso</Action></div><div className="admin-card-grid">{data.notices.map(n=><article className={`admin-entity-card admin-notice-card notice-${normalizeNoticeType(n.type||n.category)}`} key={n.id}><div className="admin-card-title"><span className="admin-card-icon"><Bell size={20}/></span><div><button type="button" className="admin-notice-select" onClick={()=>openNotice(n)} aria-label={`Selecionar aviso ${n.title}`}>{n.title}</button><small>{noticeTypeText(n.type||n.category)} · {noticeAudienceText(n.audience)}</small></div><Chip good={noticeIsActive(n)}>{noticeIsActive(n)?'Ativo':'Inativo'}</Chip></div><p>{n.message}</p>{(n.targetPlanSlug||n.targetUserId||n.startsAt||n.endsAt||n.blocksApp||n.requiresAck)&&<div className="admin-notice-details">{n.targetPlanSlug&&<span>Plano: {data.plans.find(plan=>plan.slug===n.targetPlanSlug)?.name||n.targetPlanSlug}</span>}{n.targetUserId&&<span>Usuário: {data.users.find(user=>user.id===n.targetUserId)?.name||n.targetUserId}</span>}{(n.startsAt||n.endsAt)&&<span>Período: {n.startsAt?prettyDate(n.startsAt):'Imediato'} – {n.endsAt?prettyDate(n.endsAt):'Sem término'}</span>}{n.blocksApp&&<span>Bloqueia o acesso ao sistema</span>}{n.requiresAck&&<span>Exige confirmação de leitura</span>}</div>}<div className="admin-card-actions"><Action icon={Pencil} onClick={()=>openNotice(n)}>Editar aviso</Action><Action onClick={()=>void run(()=>api!.saveNotice({...n,isActive:!noticeIsActive(n),status:noticeIsActive(n)?'inactive':'active'},n.id),noticeIsActive(n)?'Aviso desativado.':'Aviso ativado.','notices')}>{noticeIsActive(n)?'Desativar':'Ativar'}</Action><Action critical icon={Trash2} onClick={()=>askConfirmation('Remover aviso',`O aviso "${n.title}" será removido.`, 'Remover',()=>void run(()=>api!.deleteNotice(n.id),'Aviso removido.','notices'))}>Remover</Action></div></article>)}</div>{!data.notices.length&&!loading&&<Empty>Nenhum aviso publicado.</Empty>}</div>}{tab==='documents'&&<div className="admin-panel"><div className="admin-panel-head"><div><h3>Termos e comprovantes</h3><p>Monte o documento, confira a prévia e utilize a impressão em PDF.</p></div></div><div className="admin-document-grid"><form className="admin-document-form" onSubmit={e=>{e.preventDefault();window.print()}}><label className="admin-field"><span>Tipo de documento</span><select value={documents.kind} onChange={e=>setDocuments(v=>({...v,kind:e.target.value}))}><option value="adesao">Termo de adesão e ciência</option><option value="comprovante">Comprovante de pagamento</option><option value="renovacao">Termo de renovação</option></select></label><label className="admin-field"><span>Plano</span><select value={documents.planId} onChange={e=>setDocuments(v=>({...v,planId:e.target.value}))}><option value="">Selecione um plano</option>{data.plans.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>{field(documents.name,v=>setDocuments(x=>({...x,name:v})),'Nome do cliente',{required:true})}{field(documents.email,v=>setDocuments(x=>({...x,email:v})),'E-mail',{type:'email'})}{field(documents.cpf,v=>setDocuments(x=>({...x,cpf:v})),'CPF/CNPJ')}{field(documents.date,v=>setDocuments(x=>({...x,date:v})),'Data do documento',{type:'date'})}{field(documents.amount,v=>setDocuments(x=>({...x,amount:v})),'Valor pago (R$)',{type:'number',min:'0',step:'0.01'})}<label className="admin-field"><span>Forma de pagamento</span><select value={documents.payment} onChange={e=>setDocuments(x=>({...x,payment:e.target.value}))}><option>Pix</option><option>Boleto</option><option>Cartão</option><option>Transferência</option></select></label>{field(documents.signature,v=>setDocuments(x=>({...x,signature:v})),'Responsável pela emissão')}<button className="admin-action strong" type="submit"><Download size={15}/> Imprimir / salvar PDF</button></form><div className="admin-document-preview" id="admin-print-area"><span className="admin-document-mark">SURVEYOR · DOCUMENTO ADMINISTRATIVO</span><h2>{documents.kind==='adesao'?'TERMO DE ADESÃO E CIÊNCIA':documents.kind==='renovacao'?'TERMO DE RENOVAÇÃO':'COMPROVANTE DE PAGAMENTO'}</h2><h4>{data.plans.find(p=>p.id===documents.planId)?.name||'Plano não selecionado'}</h4><hr/><p><b>CLIENTE</b> {documents.name||'Não preenchido'}</p><p><b>DOCUMENTO</b> {documents.cpf||'Não informado'}</p><p><b>E-MAIL</b> {documents.email||'Não informado'}</p><p><b>PLANO</b> {data.plans.find(p=>p.id===documents.planId)?.name||'Não informado'}</p><p><b>VALOR</b> {documents.amount?Number(documents.amount).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'Não informado'}</p><p><b>PAGAMENTO</b> {documents.payment}</p><p><b>DATA</b> {shortDate(documents.date)}</p><hr/><p>Documento elaborado a partir dos dados informados. Confirme as informações e os termos aplicáveis antes da emissão.</p><div className="admin-signature-line">{documents.signature||'Responsável pela emissão'}</div></div></div></div>}
    {tab==='security'&&<div className="admin-panel"><div className="admin-panel-head"><div><h3>Visão operacional</h3><p>Sessões, acessos recentes e registros de atividade retornados pelo servidor.</p></div></div><div className="admin-stats inside"><Stat icon={Activity} label="Sessões retornadas" value={data.sessions.length}/><Stat icon={Shield} label="Registros de auditoria" value={data.audits.length}/><Stat icon={LockKeyhole} label="Tentativas de acesso" value={data.attempts.length}/></div><h3 className="admin-subheading">Sessões registradas</h3><AdminDataTable rows={data.sessions.map((s,i)=>({...s,__rowId:String(s.id||s.userId||i)} as Raw & {__rowId:string}))} getId={s=>String(s.__rowId)} label="sessões" emptyText="Nenhuma sessão retornada." loading={loading} columns={[{id:'user',label:'USUÁRIO',value:s=>human(s.userEmail||s.email||s.userId)},{id:'status',label:'ESTADO',value:s=>human(s.status||s.state||s.online)},{id:'lastSeen',label:'ÚLTIMO ACESSO',value:s=>String(s.lastLogin||s.lastActiveAt||s.updatedAt||'')}]} rowActions={s=>Boolean(s.userId)&&String(s.userId)!==session?.user?.id?<Action onClick={()=>askConfirmation('Encerrar sessão','A sessão deste usuário será encerrada.','Encerrar',()=>void run(()=>api!.remoteLogout(String(s.userId)),'Solicitação de encerramento enviada.'))}>Logout remoto</Action>:null}/><h3 className="admin-subheading">Auditoria recente</h3><AdminDataTable rows={data.audits.map((a,i)=>({...a,__rowId:String(a.id||i)}))} getId={a=>String(a.__rowId)} label="registros" emptyText="Nenhuma atividade registrada." loading={loading} columns={[{id:'date',label:'DATA',value:a=>String(a.createdAt||a.timestamp||'')},{id:'user',label:'USUÁRIO',value:a=>human(a.userEmail||a.email||a.userId)},{id:'event',label:'EVENTO',value:a=>human(a.action||a.event)}]}/><h3 className="admin-subheading">Tentativas de login</h3><AdminDataTable rows={data.attempts.map((a,i)=>({...a,__rowId:String(a.id||i)} as Raw & {__rowId:string}))} getId={a=>String(a.__rowId)} label="tentativas" emptyText="Nenhuma tentativa de login retornada." loading={loading} columns={[{id:'date',label:'DATA',value:a=>String(a.createdAt||a.timestamp||'')},{id:'account',label:'CONTA',value:a=>human(a.email||a.userEmail)},{id:'result',label:'RESULTADO',value:a=>human(a.result||a.status||a.success)}]}/></div>}
   </main></div>
  {modal==='model-access'&&activeModel&&<Dialog title={`Acessos ao modelo ${activeModel.name}`} subtitle={activeModel.restricted?'Selecione os usuários autorizados':'Modelo global: todos os usuários autorizados ao Memorial têm acesso'} onClose={()=>setModal(null)}><div className="admin-model-access"><SearchField value={modelSearch} change={setModelSearch} placeholder="Pesquisar usuário ou e-mail"/><div className="admin-model-user-list">{data.users.filter(u=>!u.isSubuser).filter(u=>`${u.name} ${u.email}`.toLowerCase().includes(modelSearch.toLowerCase())).map(u=><label key={u.id} className="admin-model-user"><input type="checkbox" disabled={!activeModel.restricted||busy} checked={activeModel.restricted?modelAccess.includes(u.id):true} onChange={e=>setModelAccess(prev=>e.target.checked?[...new Set([...prev,u.id])]:prev.filter(id=>id!==u.id))}/><span><b>{u.name||'Sem nome'}</b><small>{u.email}</small></span></label>)}</div>{!activeModel.restricted&&<p className="admin-note">A API atual define este modelo como global. Para controlar individualmente, é necessário habilitar essa regra também no servidor.</p>}<div className="admin-dialog-footer"><Action onClick={()=>setModal(null)}>Fechar</Action>{activeModel.restricted&&<Action primary disabled={busy} onClick={()=>void saveModelAccess()}>{busy?'Salvando...':'Salvar acessos'}</Action>}</div></div></Dialog>}
  {modal==='user'&&<Dialog title={editId?'Editar usuário':'Criar usuário'} onClose={()=>setModal(null)} subtitle="Dados de acesso, perfil, plano e vigência"><form className="admin-dialog-form" onSubmit={e=>{e.preventDefault();const values:Raw={name:formText('name'),role:formText('role'),status:formText('status'),planSlug:formText('planSlug'),expiresAt:formText('expiresAt')?`${formText('expiresAt')}T23:59:59-03:00`:null,phone:formText('phone'),whatsapp:formText('phone')};const original=selected as AdminUser|null;const body:Raw=editId&&original?Object.fromEntries(Object.entries(values).filter(([k,v])=>{if(k==='expiresAt')return String(v||'').slice(0,10)!==String(original.expiresAt||'').slice(0,10);if(k==='phone'||k==='whatsapp')return String(v||'')!==String(original.phone||original.whatsapp||'');return String(v??'')!==String(original[k]??'')})):values;if(!editId){body.email=formText('email').trim().toLowerCase();body.password=formText('password');body.creationRequestId=crypto.randomUUID();body.accountSource='admin';body.emailVerified=true;body.subscriptionStartedAt=new Date().toISOString();body.paymentMethod='manual';body.paymentAmountCents=0;}else if(formText('password'))body.password=formText('password');if(editId&&!Object.keys(body).length){setModal(null);setSuccess('Nenhuma alteração para salvar.');return;}void run(()=>saveUserConfirmed(body,editId),'Usuário gravado e confirmado na API.','users')}}>{field(formText('name'),v=>update('name',v),'Nome completo',{required:true})}{field(formText('email'),v=>update('email',v),'E-mail de acesso',{type:'email',required:true,disabled:!!editId})}{field(formText('phone'),v=>update('phone',v),'Telefone de contato')} {field(formText('password'),v=>update('password',v),editId?'Nova senha (opcional)':'Senha de acesso',{type:'password',required:!editId,})}<label className="admin-field"><span>Perfil</span><select value={formText('role')} onChange={e=>update('role',e.target.value)}><option value="user">Usuário</option><option value="technician">Técnico</option><option value="admin">Administrador</option></select></label><label className="admin-field"><span>Plano</span><select value={formText('planSlug')} onChange={e=>update('planSlug',e.target.value)}><option value="">Sem plano</option>{data.plans.map(p=><option key={p.id} value={p.slug}>{p.name}</option>)}</select></label><label className="admin-field"><span>Status</span><select value={formText('status')} onChange={e=>update('status',e.target.value)}><option value="active">Ativo</option><option value="blocked">Bloqueado</option><option value="expired">Vencido</option><option value="pending">Pendente</option></select></label>{field(formText('expiresAt'),v=>update('expiresAt',v),'Vencimento',{type:'date'})}<div className="admin-renew-buttons"><span>Renovação:</span>{[30,365].map(days=><Action key={days} onClick={()=>{const base=new Date(formText('expiresAt')?`${formText('expiresAt')}T12:00:00`:Date.now());const start=base.getTime()>Date.now()?base:new Date();start.setDate(start.getDate()+days);update('expiresAt',start.toISOString().slice(0,10));}}>+ {days} dias</Action>)}</div><div className="admin-dialog-footer"><Action onClick={()=>setModal(null)}>Cancelar</Action><button type="submit" disabled={busy} className="admin-action strong">{busy?'Salvando...':'Salvar usuário'}</button></div></form></Dialog>}
  {modal==='detail'&&selected&&<Dialog title={human(selected.name)} subtitle={human(selected.email)} onClose={()=>setModal(null)} wide><div className="admin-detail-summary"><Stat icon={Wallet} label="Plano" value={displayPlan(selected as AdminUser)}/><Stat icon={Activity} label="Último acesso" value={prettyDate((selected as AdminUser).lastLogin)}/><Stat icon={Shield} label="Status" value={statusText((selected as AdminUser).status)}/></div><div className="admin-detail-actions"><Action icon={Pencil} onClick={()=>openUser(selected as AdminUser)}>Editar usuário</Action><Action icon={Users} onClick={()=>void openTeam(selected as AdminUser)}>Editar equipe</Action><Action icon={Mail} onClick={()=>{setForm({email:''});setModal('email')}}>Alterar e-mail</Action>{selected.id!==session?.user?.id&&<><Action onClick={()=>void run(()=>api!.saveUser({status:(selected as AdminUser).status==='blocked'?'active':'blocked'},selected.id), 'Status atualizado.')}>{(selected as AdminUser).status==='blocked'?'Desbloquear':'Bloquear'}</Action><Action onClick={()=>{askConfirmation('Encerrar sessões','Todas as sessões deste usuário serão encerradas.','Encerrar sessões',()=>void run(()=>api!.remoteLogout(selected.id),'Sessões encerradas.'))}}>Logout remoto</Action><Action icon={Trash2} critical onClick={()=>{askConfirmation('Excluir conta',`A conta de ${selected.name} e seus acessos serão removidos.`,'Excluir conta',()=>void run(()=>api!.removeUser(selected.id),'Conta removida.'))}}>Excluir conta</Action></>}</div></Dialog>}
  {modal==='email'&&selected&&<Dialog title="Alterar e-mail de acesso" subtitle={human(selected.email)} onClose={()=>setModal(null)}><form className="admin-dialog-form" onSubmit={e=>{e.preventDefault();askConfirmation('Alterar e-mail de acesso','O e-mail de acesso será atualizado e as notificações configuradas serão enviadas.','Confirmar alteração',()=>void run(()=>api!.changeEmail(selected.id,{email:formText('email').trim().toLowerCase(),emailVerified:true,notifyNewEmail:true,notifyOldEmail:true}),'E-mail atualizado.'))}}>{field(formText('email'),v=>update('email',v),'Novo e-mail',{type:'email',required:true})}<div className="admin-dialog-footer"><Action onClick={()=>setModal(null)}>Cancelar</Action><button type="submit" className="admin-action strong" disabled={busy}>Confirmar alteração</button></div></form></Dialog>}
  {modal==='team'&&selected&&<Dialog title={`Equipe de ${human(selected.name)}`} subtitle="Vínculos e licenças da assinatura" onClose={()=>setModal(null)} wide><div className="admin-detail-summary"><Stat icon={Wallet} label="Plano" value={displayPlan(selected as AdminUser)}/><Stat icon={Users} label="Vagas" value={human(obj(teamInfo?.team||teamInfo).totalSeats,'Conforme assinatura')}/><Stat icon={Database} label="Projetos" value={human(obj(teamInfo?.team||teamInfo).projectCount,'Compartilhados')}/></div><div className="admin-dialog-form admin-team-edit">{field(formText('teamName'),v=>update('teamName',v),'Nome da equipe')}<Action primary disabled={busy} onClick={()=>void run(()=>api!.updateTeam(selected.id,{name:formText('teamName')}),'Equipe atualizada.','teams')}>Salvar nome</Action></div><div className="admin-team-header"><h3 className="admin-subheading">Membros da equipe</h3><Action icon={Plus} onClick={()=>setMemberOpen(v=>!v)}>{memberOpen?"Cancelar inclusão":"Adicionar membro"}</Action></div>{memberOpen&&<form className="admin-dialog-form admin-member-form" onSubmit={e=>{e.preventDefault();if(!selected)return;void manageMember(selected.id,()=>api!.createMember(selected.id,{...memberForm}),"Membro adicionado à equipe.")}}><label className="admin-field"><span>Nome</span><input required value={memberForm.name} onChange={e=>setMemberForm(m=>({...m,name:e.target.value}))}/></label><label className="admin-field"><span>E-mail</span><input type="email" required value={memberForm.email} onChange={e=>setMemberForm(m=>({...m,email:e.target.value}))}/></label><label className="admin-field"><span>Senha inicial</span><input type="password"  required value={memberForm.password} onChange={e=>setMemberForm(m=>({...m,password:e.target.value}))}/></label><label className="admin-field"><span>Perfil</span><select value={memberForm.role} onChange={e=>setMemberForm(m=>({...m,role:e.target.value}))}><option value="user">Usuário</option><option value="technician">Técnico</option><option value="collaborator">Colaborador</option></select></label><div className="admin-dialog-footer"><button className="admin-action strong" disabled={busy} type="submit">Adicionar à equipe</button></div></form>}<AdminDataTable rows={teamMembers(teamInfo).map((m,i)=>({...m,__rowId:String(m.id||m.email||i)} as Raw & {__rowId:string}))} getId={m=>String(m.__rowId)} label="membros" emptyText="Nenhum membro nesta equipe." columns={[{id:'user',label:'USUÁRIO',value:m=>`${human(m.name)} ${human(m.email)}`},{id:'role',label:'PERFIL',value:m=>human(m.role)},{id:'status',label:'STATUS',value:m=>human(m.status)}]} rowActions={m=>Boolean(m.id)&&m.id!==selected.id?<Action critical onClick={()=>askConfirmation('Desvincular membro','O vínculo deste membro será removido da equipe.','Desvincular',()=>void manageMember(selected.id,()=>api!.deleteMember(String(m.id)),'Membro removido da equipe.'))}>Remover</Action>:null}/></Dialog>}
  {modal==='plan'&&<Dialog title={editId?'Editar plano':'Novo plano'} subtitle="Precificação, vigência e catálogo de permissões" onClose={()=>setModal(null)} wide><form className="admin-dialog-form" onSubmit={e=>{e.preventDefault();const body:Raw={name:formText('name'),slug:formText('slug'),priceCents:number(form.priceCents),billingCycle:formText('billingCycle'),isActive:form.isActive!==false,maxMembers:number(form.maxMembers),maxStorageMb:number(form.maxStorageMb),permissions:Array.isArray(form.permissions)?form.permissions:[]};void run(()=>api!.savePlan(body,editId),'Plano salvo.','plans')}}>{field(formText('name'),v=>update('name',v),'Nome do plano',{required:true})}{field(formText('slug'),v=>update('slug',v),'Identificador (slug)',{required:true})}<label className="admin-field"><span>Cobrança</span><select value={formText('billingCycle')} onChange={e=>update('billingCycle',e.target.value)}><option value="monthly">Mensal</option><option value="annual">Anual</option></select></label>{field(number(form.priceCents)/100,v=>update('priceCents',Math.round(Number(v)*100)),'Preço (R$)',{type:'number',min:'0',step:'0.01'})}{field(number(form.maxMembers),v=>update('maxMembers',v),'Licenças',{type:'number',min:'1'})}{field(number(form.maxStorageMb),v=>update('maxStorageMb',v),'Armazenamento (MB)',{type:'number',min:'0'})}<label className="admin-checkbox"><input type="checkbox" checked={form.isActive!==false} onChange={e=>update('isActive',e.target.checked)}/> Plano ativo</label><h3 className="admin-subheading full">Permissões</h3><div className="admin-permission-editor">{permissions.map(([category,items])=><fieldset key={category}><legend>{category}</legend>{items.map(code=><label key={code}><input type="checkbox" checked={(Array.isArray(form.permissions)?form.permissions as string[]:[]).includes(code)} onChange={e=>{const list=Array.isArray(form.permissions)?form.permissions as string[]:[];update('permissions',e.target.checked?[...new Set([...list,code])]:list.filter(x=>x!==code))}}/>{code}</label>)}</fieldset>)}</div><div className="admin-dialog-footer"><Action onClick={()=>setModal(null)}>Cancelar</Action><button className="admin-action strong" disabled={busy} type="submit">Salvar plano</button></div></form></Dialog>}
  {modal==='layer'&&<Dialog title={editId?'Editar camada':'Nova camada'} onClose={()=>setModal(null)}><form className="admin-dialog-form" onSubmit={e=>{e.preventDefault();void run(()=>api!.saveLayer({name:formText('name'),groupId:formText('groupId'),sourceName:formText('sourceName'),serviceUrl:formText('serviceUrl'),geometryType:formText('geometryType'),style:{...obj(form.style),color:formText('color'),fillColor:formText('color')}},editId),'Camada salva.','layers')}}>{field(formText('name'),v=>update('name',v),'Nome da camada',{required:true})}<label className="admin-field"><span>Grupo</span><select value={formText('groupId')} onChange={e=>update('groupId',e.target.value)}><option value="">Sem grupo</option>{data.groups.map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label>{field(formText('sourceName'),v=>update('sourceName',v),'Fonte')}{field(formText('serviceUrl'),v=>update('serviceUrl',v),'URL do serviço',{type:'url'})}{field(formText('geometryType'),v=>update('geometryType',v),'Tipo de geometria')}{field(formText('color'),v=>update('color',v),'Cor',{type:'color'})}<div className="admin-dialog-footer"><Action onClick={()=>setModal(null)}>Cancelar</Action><button className="admin-action strong" type="submit" disabled={busy}>Salvar camada</button></div></form></Dialog>}
  {modal==='group'&&<Dialog title="Criar grupo de camadas" onClose={()=>setModal(null)}><form className="admin-dialog-form" onSubmit={e=>{e.preventDefault();void run(()=>api!.createGroup(formText('name')),'Grupo criado.','layers')}}>{field(formText('name'),v=>update('name',v),'Nome do grupo',{required:true})}<div className="admin-dialog-footer"><button type="submit" className="admin-action strong" disabled={busy}>Criar grupo</button></div></form></Dialog>}
  {confirmation&&<Dialog title={confirmation.title} subtitle={confirmation.description} onClose={()=>setConfirmation(null)} closeOnBackdrop={false}><div className="admin-dialog-footer"><Action onClick={()=>setConfirmation(null)}>Cancelar</Action><Action critical onClick={()=>{const action=confirmation.action;setConfirmation(null);action()}}>{confirmation.label}</Action></div></Dialog>}
  {modal==='notice'&&<Dialog title={editId?'Editar aviso':'Criar aviso'} subtitle="Defina o conteúdo, o público e o período de exibição." onClose={()=>setModal(null)} wide><form className="admin-dialog-form" onSubmit={e=>{e.preventDefault();const audience=normalizeNoticeAudience(form.audience);void run(()=>api!.saveNotice({title:formText('title').trim(),message:formText('message').trim(),type:normalizeNoticeType(form.type),category:normalizeNoticeType(form.type),displayMode:formText('displayMode'),deliveryMode:formText('displayMode'),status:formText('status'),isActive:formText('status')==='active',audience,targetPlanSlug:audience==='plan'?formText('targetPlanSlug'):null,targetUserId:audience==='user'?formText('targetUserId'):null,startsAt:fromLocalDateTime(form.startsAt),endsAt:fromLocalDateTime(form.endsAt),blocksApp:Boolean(form.blocksApp),requiresAck:Boolean(form.requiresAck)},editId),'Aviso salvo.','notices')}}>{field(formText('title'),v=>update('title',v),'Título',{required:true,maxLength:120})}<label className="admin-field full"><span>Mensagem</span><textarea required rows={5} maxLength={4000} value={formText('message')} onChange={e=>update('message',e.target.value)}/></label><label className="admin-field"><span>Exibição</span><select value={formText('displayMode')} onChange={e=>update('displayMode',e.target.value)}><option value="notification">Notificação</option><option value="popup">Pop-up</option><option value="banner">Faixa fixa</option><option value="maintenance">Manutenção</option><option value="login-expiration">Aviso de login</option><option value="release">Novidade</option></select></label><label className="admin-field"><span>Tipo</span><select value={formText('type')} onChange={e=>update('type',e.target.value)}><option value="info">Informação</option><option value="success">Sucesso</option><option value="warning">Alerta</option><option value="danger">Urgente</option><option value="maintenance">Manutenção</option></select></label><label className="admin-field"><span>Público</span><select value={formText('audience')} onChange={e=>update('audience',e.target.value)}><option value="all">Todos</option><option value="users">Usuários ativos</option><option value="admins">Administradores</option><option value="plan">Plano específico</option><option value="user">Usuário específico</option></select></label>{formText('audience')==='plan'&&<label className="admin-field"><span>Plano</span><select required value={formText('targetPlanSlug')} onChange={e=>update('targetPlanSlug',e.target.value)}><option value="">Selecione um plano</option>{data.plans.map(plan=><option key={plan.id} value={plan.slug}>{plan.name}</option>)}</select></label>}{formText('audience')==='user'&&<label className="admin-field"><span>Usuário</span><select required value={formText('targetUserId')} onChange={e=>update('targetUserId',e.target.value)}><option value="">Selecione um usuário</option>{data.users.map(user=><option key={user.id} value={user.id}>{user.name} · {user.email}</option>)}</select></label>}<label className="admin-field"><span>Status</span><select value={formText('status')} onChange={e=>update('status',e.target.value)}><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label>{field(formText('startsAt'),v=>update('startsAt',v),'Início',{type:'datetime-local'})}{field(formText('endsAt'),v=>update('endsAt',v),'Término',{type:'datetime-local'})}<label className="admin-checkbox"><input type="checkbox" checked={Boolean(form.blocksApp)} onChange={e=>update('blocksApp',e.target.checked)}/> Bloquear o acesso enquanto o aviso estiver ativo</label><label className="admin-checkbox"><input type="checkbox" checked={Boolean(form.requiresAck)} onChange={e=>update('requiresAck',e.target.checked)}/> Exigir confirmação de leitura</label><div className="admin-dialog-footer"><Action onClick={()=>setModal(null)}>Cancelar</Action><button className="admin-action strong" type="submit" disabled={busy}>{busy?'Salvando...':'Salvar aviso'}</button></div></form></Dialog>}
 </div>;
}
function Stat({label,value,icon:Icon}:{label:string;value:string|number;icon:LucideIcon}){return <div className="admin-stat"><span className="admin-stat-icon"><Icon size={21}/></span><div><small>{label}</small><strong>{value}</strong></div></div>}
function SearchField({value,change,placeholder}:{value:string;change:(v:string)=>void;placeholder:string}){return <label className="admin-search"><Search size={16}/><input value={value} onChange={e=>change(e.target.value)} placeholder={placeholder} aria-label={placeholder}/></label>}
function Empty({children}:{children:ReactNode}){return <div className="admin-empty"><FolderOpen size={20}/><p>{children}</p></div>}
